films.V135NeverContent:
// V135NeverContent: the 1899 record car as the film's real object. Three plates of the story's own photos on the paper, each
// whole in a white card, greyscale, with hand marks on the one thing the line is about: the hall shot (the car whole), the
// name painted on its body ringed, and Porsche's hybrid with its engine block and hub ringed.
import React from 'react';
import {Img, staticFile, useCurrentFrame} from 'remotion';
import {cueFrame, Land, lead, PictureBand} from '../common';
import type {SceneCtx} from '../../types';
import {Card, FitText, Quiet, S, drift} from '../kit/p2';
import {Ink, type InkMark} from '../kit/ink';

type P = {
  shot?: 'hall' | 'name' | 'hybrid';
  /** the key moment (a chunk or "1.2s"): the punch lands */
  hitAt?: number | string;
  /** the punch under the plate (the name shot) */
  line?: string;
  /** a quiet line over the plate (Latin) */
  note?: string;
};

type Plate = {pw: number; ph: number; y: number; k: number; dx: number; dy: number};

// each photo as a whole plate 780 px wide on the stage (x 150..930, air on both sides); k scales the photo, dx dy crop its scan edge
const PLATES = {
  hall: {pw: 1600, ph: 1200, y: 500, k: 0.4875, dx: 0, dy: 0},
  name: {pw: 1000, ph: 440, y: 560, k: 0.816, dx: -18, dy: -8},
  hybrid: {pw: 1600, ph: 1067, y: 520, k: 0.4875, dx: 0, dy: 0},
};
const CW = 780;
const CX = 150;

export const V135NeverContent: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => {
  const frame = useCurrentFrame();
  const shot = p.shot ?? 'hall';
  const pl: Plate = shot === 'name' ? PLATES.name : shot === 'hybrid' ? PLATES.hybrid : PLATES.hall;
  const ch = Math.round((pl.ph * CW) / pl.pw);
  const base = lead(ctx);
  const hit = Math.max(base + 14, cueFrame(ctx, p.hitAt ?? 1));
  const room = {x: CX, y: pl.y, w: CW, h: ch};
  // the photo inside its card: a slow push towards the subject (the card itself stays whole and still)
  const push = 1 + 0.035 * Math.min(1, frame / Math.max(1, ctx.dur));
  const iw = pl.pw * pl.k;
  const ih = pl.ph * pl.k;
  const marks: InkMark[] =
    shot === 'name'
      ? [{kind: 'circle', box: {x: 432, y: 606, w: 116, h: 50}, at: base + 10, within: room}]
      : shot === 'hybrid'
        ? [
            {kind: 'circle', box: {x: 546, y: 568, w: 128, h: 128}, at: base + 10, within: room},
            {kind: 'circle', box: {x: 160, y: 804, w: 180, h: 178}, at: base + 36, within: room},
          ]
        : [{kind: 'circle', box: {x: 368, y: 610, w: 108, h: 60}, at: base + 12, within: room}];
  const focus = shot === 'name' ? {x: 490, y: 630} : {x: 540, y: pl.y + ch / 2};
  const img: React.CSSProperties = {position: 'absolute', left: pl.dx, top: pl.dy, width: iw, height: ih, filter: 'grayscale(1) contrast(1.08)', transform: `scale(${push.toFixed(4)})`, transformOrigin: `${focus.x - CX}px ${focus.y - pl.y}px`};
  return (
    <PictureBand camera={false}>
      <div style={{position: 'absolute', inset: 0, ...drift(frame, ctx.dur, focus)}}>
        {p.note ? <Quiet text={p.note} x={S.cx} y={pl.y - 64} w={CW - 40} align="center" latin at={base} /> : null}
        <Card x={CX} y={pl.y} w={CW} h={ch} r={18}>
          {shot === 'name' ? <Img src={staticFile('photos/story-ev-is-old-2.jpg')} style={img} /> : shot === 'hybrid' ? <Img src={staticFile('photos/story-ev-is-old-5.jpg')} style={img} /> : <Img src={staticFile('photos/story-ev-is-old-3.jpg')} style={img} />}
        </Card>
        <Ink marks={marks} end={ctx.dur} room={room} />
        {shot === 'name' && p.line ? <FitText text={p.line} x={S.cx} y={pl.y + ch + 110} w={700} size={110} min={72} maxLines={2} align="center" anim="slam" at={hit} /> : null}
      </div>
      {shot === 'name' ? <Land at={hit} /> : null}
    </PictureBand>
  );
};
